export const HORIZON=60;
export const DEFAULTS=Object.freeze({lag:4,gain:.45,review:1,response:.3,scenario:'shift'});
export const SCENARIOS=Object.freeze({shift:{name:'A change in demand',description:'Withdrawal rises, then falls. The signal reaches you later.'},wave:{name:'A moving demand',description:'Withdrawal changes gradually, with a shorter disturbance in the middle.'},steady:{name:'A quiet system',description:'Almost steady withdrawal. A useful place to try a stronger response.'}});
const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
export function config(raw={}){const value=(key,fallback,lo,hi)=>Number.isFinite(Number(raw[key]))?clamp(Number(raw[key]),lo,hi):fallback;return{lag:Math.round(value('lag',4,0,12)),gain:value('gain',.45,0,1.5),review:Math.round(value('review',1,1,8)),response:value('response',.3,.1,1),scenario:Object.hasOwn(SCENARIOS,raw.scenario)?raw.scenario:'shift'};}
export function withdrawal(t,scenario='shift'){if(scenario==='shift')return t<11?5:t<29?7:t<44?3.5:5;if(scenario==='wave')return 5+1.8*Math.sin(t/6)+(t>=23&&t<31?1:0);return 5+.15*Math.sin(t/3);}
export function createRun(settings={}){return{settings:config(settings),tick:0,level:50,pump:5,command:5,spill:0,unmet:0,history:[{tick:0,level:50,pump:5,command:5,withdrawal:5,spill:0,unmet:0}]};}
export function observation(state){return state.history[Math.max(0,state.tick-state.settings.lag)].level;}
export function step(state,command){if(state.tick>=HORIZON)throw Error('The run is complete.');if(!Number.isFinite(command)||command<0||command>12)throw Error('Inflow must be between 0 and 12 units per tick.');const tick=state.tick+1,pump=state.pump+state.settings.response*(command-state.pump),drain=withdrawal(tick,state.settings.scenario),raw=state.level+pump-drain,spill=Math.max(0,raw-100),unmet=Math.max(0,-raw),level=clamp(raw,0,100),row={tick,level,pump,command,withdrawal:drain,spill,unmet};return{...state,tick,pump,command,level,spill:state.spill+spill,unmet:state.unmet+unmet,history:[...state.history,row]};}
export function ruleCommand(state){return state.tick%state.settings.review===0?clamp(5+state.settings.gain*(50-observation(state)),0,12):state.command;}
export function simulate(settings={}){let state=createRun(settings);while(state.tick<HORIZON)state=step(state,ruleCommand(state));return state;}
export function metrics(state){const rows=state.history.slice(1);return{meanError:rows.length?rows.reduce((sum,r)=>sum+Math.abs(r.level-50),0)/rows.length:0,inBand:rows.length?rows.filter(r=>Math.abs(r.level-50)<=5).length/rows.length:1,spill:state.spill,unmet:state.unmet,effort:rows.reduce((sum,r,i)=>sum+Math.abs(r.command-state.history[i].command),0)};}
export function restore(raw){if(!raw||!Array.isArray(raw.commands)||raw.commands.length>HORIZON)throw Error('Invalid saved run.');let state=createRun(raw.settings);for(const command of raw.commands)state=step(state,command);return state;}
export function serialize(state){return{settings:state.settings,commands:state.history.slice(1).map(r=>r.command)};}
export function readings(state){return state.history.map((r,i)=>({tick:r.tick,level:state.history[Math.max(0,i-state.settings.lag)].level}));}
